insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('72bd19c8-056a-55bf-b037-8ea80eaba340', '41e08c4c-84a4-5f13-839e-992a3011053e', 'A certain hybrid car uses 39 gallons of gasoline to travel 1,950 miles. At this rate, how many kilometers does the car travel using 39 gallons of gasoline? (Use 1 mile = 1.6 kilometers.)', '["312", "3,120", "31,200", "31.2"]'::jsonb, 1, null),
  ('08a6b0a7-6ac7-5d31-86c5-6b0a37a05886', '41e08c4c-84a4-5f13-839e-992a3011053e', 'The function $h$ is defined by $h(x) = 4x - 9$. What is the value of $h(-3)$?', '["$21$", "$13$", "$-13$", "$-21$"]'::jsonb, 2, null),
  ('e5e809f1-a47f-52a2-879f-82e9b98e878d', '41e08c4c-84a4-5f13-839e-992a3011053e', '$10x = 110$
$8x - 86 = y$
The solution to the given system of equations is $(x,y)$. What is the value of $y$?', '["86", "11", "10", "2"]'::jsonb, 3, null),
  ('874bba32-2d46-59d7-bbfe-eec14d3c21af', '41e08c4c-84a4-5f13-839e-992a3011053e', 'Which expression is equivalent to $7x^{5} - 6x^{4} + 9x^{3}$?', '["$x^{4}(7x - 6)$", "$x^{3}(7x^{2} - 6x + 9)$", "$9x^{3}(7x^{2} - 6x + 1)$", "$6x^{5}(-6x^{4} + 9x^{3} + 1)$"]'::jsonb, 4, null),
  ('7e1d8c07-c00c-5e56-95e2-917c97101259', '41e08c4c-84a4-5f13-839e-992a3011053e', '$y = 0$
$y = 8(x^{2} - 36)$
Which ordered pair $(x,y)$ is a solution to the given system of equations?', '["(0, 6)", "(0, 36)", "(6, 0)", "(36, 0)"]'::jsonb, 5, null),
  ('65471c7c-699c-5253-8d05-9a1694cf164b', '41e08c4c-84a4-5f13-839e-992a3011053e', 'A group of students purchase ice cream cones and ice cream sundaes. The cones cost $1.40$ USD each, and the cost for 19 sundaes is $64.60$ USD. The total cost for the cones and sundaes is $85.60$ USD. Which equation represents this situation, where $x$ is the number of cones purchased and $y$ is the number of sundaes purchased?', '["$1.40x + 64.60y = 85.60$", "$64.60x + 1.40y = 85.60$", "$3.40x + 1.40y = 85.60$", "$1.40x + 3.40y = 85.60$"]'::jsonb, 6, null),
  ('49662423-e8c3-5be2-8dc2-6600e84f6498', '41e08c4c-84a4-5f13-839e-992a3011053e', 'Hakim has a bag of $50$ tiles, where $45$ are labeled with a letter and $5$ are blank. If Hakim selects a tile from the bag at random, what is the probability of selecting a blank tile? (Express your answer as a decimal or fraction, not as a percent.)', '[]'::jsonb, 7, null),
  ('0de80ec8-b592-5fd2-9157-d87d0a0b53b2', '41e08c4c-84a4-5f13-839e-992a3011053e', 'In $\triangle DEF$, the measure of $\angle D$ is $114°$. Which of the following could be the measure, in degrees, of $\angle E$?', '["115", "90", "67", "65"]'::jsonb, 8, null),
  ('ba907817-51fd-58e7-a3d3-72d66f7c5908', '41e08c4c-84a4-5f13-839e-992a3011053e', 'The shaded region shown represents the solutions to which inequality?', '["$y > 3x + 7$", "$y > 3x - 7$", "$y < 3x + 7$", "$y < 3x - 7$"]'::jsonb, 9, '![figure](/q/may25/001.webp)'),
  ('24c11468-f360-58c7-8a8e-e8ad8723b8c7', '41e08c4c-84a4-5f13-839e-992a3011053e', 'Which expression is equivalent to $20x^{2} + 3 + 5x^{2}$?', '["$25x^{4} + 3$", "$25x^{2} + 3$", "$28x^{4}$", "$28x^{2}$"]'::jsonb, 10, null),
  ('19ba731e-2f09-54ed-9feb-086b6a557559', '41e08c4c-84a4-5f13-839e-992a3011053e', 'A company opens an account with an initial balance of $35,600$ USD. The account earns interest, and no additional deposits or withdrawals are made. The account balance is given by an exponential function $A$, where $A(t)$ is the account balance, in dollars, $t$ years after the account is opened. The account balance after 15 years is $129,672.38$ USD. Which equation could define $A$?', '["$A(t) = 35,600.00(1.09)^{t}$", "$A(t) = 35,600.00(0.09)^{t}$", "$A(t) = 94,072.38(1.09)^{t}$", "$A(t) = 94,072.38(0.09)^{t}$"]'::jsonb, 11, null),
  ('7742458d-287b-5e59-86be-4a3477b44fa8', '41e08c4c-84a4-5f13-839e-992a3011053e', 'What is the y-intercept of the graph of $y = 14^{x}$ in the xy-plane?', '["$(0,15)$", "$(0,14)$", "$(0,1)$", "$(0,-1)$"]'::jsonb, 12, null),
  ('732b2041-2b6e-56ff-a8c3-8527076c5d2e', '41e08c4c-84a4-5f13-839e-992a3011053e', 'The function $f$ is defined by $f(x) = 2x + b$, where $b$ is a constant and $f(7) = 6$. What is the value of $b$?', '[]'::jsonb, 13, null),
  ('80f9725d-741f-5028-b3a7-925d1726e3eb', '41e08c4c-84a4-5f13-839e-992a3011053e', 'A number $f$ is 120% greater than a positive number $g$. A number $h$ is 90% less than the number $f$. The number $h$ is how many times the number $g$?', '["0.12", "0.22", "01.08", "1.98"]'::jsonb, 14, null),
  ('74585b49-115d-5532-a2aa-bd7f11b2c628', '41e08c4c-84a4-5f13-839e-992a3011053e', 'The histograms summarize the distributions of scores for team A and team B. Which statement best compares the standard deviations of scores for these teams?', '["The standard deviation of scores for team A is less than the standard deviation of scores for team B.", "The standard deviation of scores for team A is greater than the standard deviation of scores for team B.", "The standard deviation of scores for team A is equal to the standard deviation of scores for team B.", "There is not enough information to compare the standard deviations."]'::jsonb, 15, '![figure](/q/may25/002.webp)'),
  ('d9c7d587-2bbd-589e-bee5-d3c6e7baf21b', '41e08c4c-84a4-5f13-839e-992a3011053e', 'Circle A shown is defined by the equation $x^{2} + (y - 5)^{2} = 7$. Circle B (not shown) has the same radius but is translated 91 units to the right. If the equation of circle B is $(x - h)^{2} + (y - k)^{2} = a$, where $h,k,$ and $a$ are constants, what is the value of $4a$?', '[]'::jsonb, 16, '![figure](/q/may25/003.webp)'),
  ('c66ecaff-5a8e-50e5-80e7-eb85ca345251', '41e08c4c-84a4-5f13-839e-992a3011053e', 'The function $h(t) = -16t^{2} + b$ estimates an object’s height, in feet, above the ground $t$ seconds after the object is dropped, where $b$ is a constant. The function estimates that the object is 40.96 feet above the ground when it is dropped at $t = 0$. How many seconds after being dropped does the function estimate the object will hit the ground?', '[]'::jsonb, 17, null),
  ('a18bed1e-32cc-5fd8-a1ee-afe6b0d28359', '41e08c4c-84a4-5f13-839e-992a3011053e', 'The graph shows the total amount of rainfall $y$, in centimeters, from the start of a 10-hour period, where $x$ is the number of hours after the start of the period. Which of the following statements about the rainfall during this time period is true?', '["The rate of rainfall was 2 centimeters per hour between $x = 2$ and $x = 4$.", "The rate of rainfall was the greatest between $x = 4$ and $x = 10$.", "The rate of rainfall increased between $x = 0$ and $x = 2$.", "The rate of rainfall was 0 centimeters per hour between $x = 2$ and $x = 4$."]'::jsonb, 18, '![figure](/q/may25/004.webp)'),
  ('6a7f632b-96eb-59c0-8825-15588c5fd959', '41e08c4c-84a4-5f13-839e-992a3011053e', 'For a set of three consecutive integers, the result of subtracting the greatest integer from the sum of the other two integers is 48. What is the value of the greatest of the three integers?', '[]'::jsonb, 19, null),
  ('c8c098c4-bf23-5fa8-8e61-7c1e9545d881', '41e08c4c-84a4-5f13-839e-992a3011053e', 'A rectangular banner has an area of 2,300 square inches. A copy of the banner is made in which the length and width of the original banner are each increased by 20%. What is the area of the copy, in square inches?', '["2,32", "2,34", "2,76", "3,312"]'::jsonb, 20, null),
  ('eb9b5b4d-adf5-5427-940b-27267778a1dd', '41e08c4c-84a4-5f13-839e-992a3011053e', '$(x - 42)^{2} = 1$ What is the sum of the solutions to the given equation?', '["42", "43", "84", "85"]'::jsonb, 21, null),
  ('550f6335-cb1a-5c0a-86f0-e45a224b4134', '41e08c4c-84a4-5f13-839e-992a3011053e', '$5(kx - n) = -\frac{65}{14}x - \frac{85}{18}$
In the given equation, $k$ and $n$ are constants and $n > 1$. The equation has no solution. What is the value of $k$?', '["-13/14", "$-0.128$", "3/2", "$0,52$"]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('72bd19c8-056a-55bf-b037-8ea80eaba340', 1, null, '**Choice B is correct.** The car travels 1,950 miles on 39 gallons; to convert miles to kilometers use $1 \text{mile} =$ $1.6 \text{km}$. So $1,950 \times 1.6 = 1,950 \times \frac{16}{10} = (1,950 \times 16)/10 = 31,200/10 = 3,120$ km.
**Choice A is incorrect.** 312 is 1/10 of the correct value; it results from an extra division by 10.
**Choice C is incorrect.** 31,200 is 10 times too large; it comes from forgetting to divide by 10 after multiplying by 16.
**Choice D is incorrect.** 31.2 is 1/100 of the correct value and reflects both an extra division by 10 and a misplaced decimal.
**Faster approach:** Convert by multiplying by $1.6$ quickly: $1,950 \times 1.6 = (1,950 \times 16)/10$. Or use $1.6 = 8/5$ so $(1,950/5) \times 8 = 390 \times 8 = 3,120$. This method works for any mile-to-kilometer conversion using 1.6.'),
  ('08a6b0a7-6ac7-5d31-86c5-6b0a37a05886', 3, null, '**Choice D is correct.** Evaluate $h(x) = 4x - 9$ at $x = -3$: $h(-3) = 4(-3) - 9 = -12 - 9 = -21$, so the value is $-21$.
**Choice A is incorrect.** $21$ is the opposite sign of the correct answer; it would correspond to $4(3) + 9$ or an arithmetic sign error.
**Choice B is incorrect.** $13$ would result from $4(3) + 1$ or from an incorrect substitution (for example, using $x = 3$ and miscomputing the constant), which does not match $h(-3)$.
**Choice C is incorrect.** $-13$ would come from $4(-1) - 9$ or $4(-3) + -1$, a miscalculation; it does not equal $4(-3) - 9$.
**Faster approach:** Direct substitution: replace $x$ with $-3$ and compute $4(-3) - 9$ to get $-21$—one quick arithmetic step suffices for every problem of this type.'),
  ('e5e809f1-a47f-52a2-879f-82e9b98e878d', 3, null, '**Choice D is correct.** From $10x = 110$ we get $x = 11$. Substitute into $y = 8x - 86$ to get $y = 8(11) - 86 =$ $88 - 86 = 2$, so $y = 2$.
**Choice A is incorrect.** $86$ is the constant subtracted in the expression for $y$, not the value of $y$ after substituting $x = 11$.
**Choice B is incorrect.** $11$ is the value of $x$, not $y$.
**Choice C is incorrect.** $10$ is neither the value of $x$ (which is $11$) nor the result of the substitution for $y$.
**Faster approach:** Solve the first equation for $x$ ($x = 110/10 = 11$) and immediately plug that into the second equation; this direct substitution is the fastest method for any two-equation linear system where one equation gives a single variable.'),
  ('874bba32-2d46-59d7-bbfe-eec14d3c21af', 1, null, '**Choice B is correct.** Factor out the greatest common monomial $x^{3}$ from each term: $7x^{5} - 6x^{4} + 9x^{3} =$ $x^{3}(7x^{2} - 6x + 9)$, which matches choice B exactly.
**Choice A is incorrect.** Factoring $x^{4}$ gives $x^{4}(7x - 6) + 9x^{3}$, so $x^{4}(7x - 6)$ omits the $9x^{3}$ term; it is not equivalent to the original expression.
**Choice C is incorrect.** Multiplying out $9x^{3}(7x^{2} - 6x + 1)$ would give coefficients $63x^{5} - 54x^{4} + 9x^{3}$, which does not match the original coefficients (63 and -54 vs. 7 and -6).
**Choice D is incorrect.** The expression $6x^{5}(-6x^{4} + 9x^{3} + 1)$ expands to terms of much higher degree and different coefficients; it is not equal to the given polynomial.
**Faster approach:** Immediately factor out the greatest common monomial (highest common power of $x$ and common numeric factor, if any). Here the highest common power is $x^{3}$, so pull out $x^{3}$ and read the resulting quadratic polynomial.'),
  ('7e1d8c07-c00c-5e56-95e2-917c97101259', 2, null, '**Choice C is correct.** The two equations give $y = 0$ and $y = 8(x^{2} - 36)$. Substitute $y = 0$ into the second equation to get $0 = 8(x^{2} - 36)$. Divide by 8: $x^{2} - 36 = 0$, so $x^{2} = 36$ and $x = \pm 6$. The ordered pairs of intersection are $(6,0)$ and $(-6,0)$; choice C, $(6,0)$, is one of these and therefore is a solution.
**Choice A is incorrect.** For $(0,6)$, $y$ would be 6, but the first equation requires $y = 0$, so $(0,6)$ cannot satisfy the system.
**Choice B is incorrect.** For $(0,36)$, $y = 36$ contradicts the first equation $y = 0$, so $(0,36)$ is not a solution.
**Choice D is incorrect.** For $(36,0)$, substitute $x = 36$ into $y = 8(x^{2} - 36)$ to get $y = 8(36^{2} - 36)$, which is not 0, so $(36,0)$ is not on the second curve and thus not a solution.
**Faster approach:** Substitute $y = 0$ into the second equation and solve $0 = 8(x^{2} - 36)$ to get $x = \pm 6$. Then scan the choices for an ordered pair with $x = 6$ or $x = -6$ and $y = 0$.'),
  ('65471c7c-699c-5253-8d05-9a1694cf164b', 3, null, '**Choice D is correct.** Each cone costs $1.40$, so cones contribute $1.40x$. Nineteen sundaes cost $64.60$, so one sundae costs $64.60/19 = 3.40$, and sundaes contribute $3.40y$. The total cost is $85.60$, giving $1.40x + 3.40y =$ $85.60$, which matches choice D.
**Choice A is incorrect.** It treats $64.60$ as the per-sundae price, which is the cost for 19 sundaes, not one sundae.
**Choice B is incorrect.** It swaps the unit prices, assigning $64.60$ per cone and $1.40$ per sundae, contradicting the problem statement.
**Choice C is incorrect.** It uses $3.40$ for cones and $1.40$ for sundaes, reversing the given prices.
**Faster approach:** Convert any multi-item total to a unit price first (divide $64.60$ by $19$ to get $3.40$ per sundae), then form the linear cost equation $($price per cone$)x + ($price per sundae$)y =$total\$.'),
  ('49662423-e8c3-5be2-8dc2-6600e84f6498', null, array['1/10']::text[], '**The correct answer is 1/10.** There are 5 blank tiles out of a total of 50 tiles, so the probability of selecting a blank tile is $\frac{5}{50} = \frac{1}{10}$, which can also be written as $0.1$.
**Faster approach:** Recognize that probability = favorable outcomes ÷ total outcomes; reduce $\frac{5}{50}$ immediately by dividing numerator and denominator by 5 to get $\frac{1}{10}$ (or 0.1).'),
  ('0de80ec8-b592-5fd2-9157-d87d0a0b53b2', 3, null, '**Choice D is correct.** In any triangle the interior angles sum to $180°$. Here $\angle D = 114°$, so $\angle E + \angle F = 180° -$ $114° = 66°$. Because $\angle F$ must be a positive angle, $\angle E$ must be less than $66°$. Choice D, $65°$, is the only given option that is less than $66°$, so it could be the measure of $\angle E$.
**Choice A is incorrect.** $115°$ is greater than $114°$ and would make the sum of the three angles exceed $180°$, so it cannot occur.
**Choice B is incorrect.** $90°$ is larger than $66°$, so combined with $114°$ it would force the third angle to be negative, which is impossible.
**Choice C is incorrect.** $67°$ is greater than $66°$, so it cannot be paired with $114°$ and a positive third angle to total $180°$.
**Faster approach:** Use the triangle-sum rule $E + F = 66°$ and immediately eliminate any choice greater than $66°$; the remaining choice is correct.'),
  ('ba907817-51fd-58e7-a3d3-72d66f7c5908', 0, null, '**Choice A is correct.** The dashed boundary line has slope 3 and a y-intercept of 7, so its equation is $y = 3x +$ $7$. The shading is the region above that line, which corresponds to the inequality $y > 3x + 7$. The line is dashed, indicating a strict inequality, so $>$ (not $\ge$) is correct.
**Choice B is incorrect.** $y > 3x - 7$ has the same slope but a y-intercept of $-7$, which would place the boundary much lower; the graph shows the boundary crossing the y-axis at about $7$, not $-7$.
**Choice C is incorrect.** $y < 3x + 7$ uses the correct line but the wrong side; it would shade below the line, whereas the graph shades above the line.
**Choice D is incorrect.** $y < 3x - 7$ has both the wrong intercept and the wrong inequality direction.
**Faster approach:** Identify the line’s y-intercept (where it crosses the y-axis) and slope from two clear points to get the equation, note that the shading is above or below the line to choose $>$ or $<$, and use the dashed/solid style to determine strict or nonstrict inequality.'),
  ('24c11468-f360-58c7-8a8e-e8ad8723b8c7', 1, null, '**Choice B is correct.** The terms $20x^{2}$ and $5x^{2}$ are like terms and add to $25x^{2}$, so the expression simplifies to $25x^{2} + 3$, which matches Choice B.
**Choice A is incorrect.** It incorrectly multiplies the exponents to get $x^{4}$ and gives $25x^{4} + 3$; adding like terms does not change exponents.
**Choice C is incorrect.** It gives $28x^{4}$, which both uses the wrong exponent ($x^{4}$) and omits the constant $+3$; neither operation is valid for simplifying the original expression.
**Choice D is incorrect.** Although it has the correct exponent $x^{2}$, $28x^{2}$ results from adding $20x^{2}$ and $5x^{2}$ to get $25x^{2}$ then incorrectly adding 3 as if it were $3x^{2}$; the constant 3 should remain separate.
**Faster approach:** Combine like terms by adding coefficients of identical powers (here $20x^{2} + 5x^{2} = 25x^{2}$) and keep constants unchanged, yielding $25x^{2} + 3$ every time.'),
  ('19ba731e-2f09-54ed-9feb-086b6a557559', 0, null, '**Choice A is correct.** The general form is $A(t) = A_{0}(1 + r)^{t}$ with initial balance $A_{0} = 35,600$. Because no deposits/withdrawals are made, the base must be $1 + r > 1$. Check the growth factor by comparing $\frac{129,672.38}{35,600} \approx 3.64248$. The 15th root of $3.64248$ is about $1.09$, so $r \approx 0.09$ and $A(t) = 35,600(1.09)^{t}$, which is choice A.
**Choice B is incorrect.** It uses $0.09^{t}$ as the base; that would represent a rapid decay (base much less than 1), but the account grows to a larger amount.
**Choice C is incorrect.** It uses the wrong initial balance $94,072.38$ instead of the given $35,600$.
**Choice D is incorrect.** It both uses the wrong initial balance and an incorrect decay base $0.09^{t}$.
**Faster approach:** Recognize the form $A_{0}(1 + r)^{t}$. Use the given initial amount to eliminate choices immediately (keep only those with $A_{0} = 35,600$), then note the account grows so the base must be $> 1$ (choose $1.09$ rather than $0.09$).'),
  ('7742458d-287b-5e59-86be-4a3477b44fa8', 2, null, '**Choice C is correct.** The y-intercept occurs at x = 0, so substitute x = 0 into $y = 14^{x}$ to get $y = 14^{0} = 1$. Thus the y-intercept is $(0,1)$.
**Choice A is incorrect.** $(0,15)$ would require $14^{0} = 15$, which is false because any nonzero base to the 0 power equals 1, not 15.
**Choice B is incorrect.** $(0,14)$ would require $14^{0} = 14$, which is false for the same reason: $14^{0} = 1$, not 14.
**Choice D is incorrect.** $(0,-1)$ would require $14^{0} = -1$, but $14^{0} = 1$ and exponential functions with positive base are positive for all real exponents.
**Faster approach:** For any nonzero base $a$, $a^{0} = 1$, so plug in $x = 0$ immediately to get the y-intercept $(0,1)$.'),
  ('732b2041-2b6e-56ff-a8c3-8527076c5d2e', null, array['-8']::text[], '**The correct answer is -8.** Substitute $x = 7$ into $f(x) = 2x + b$ and set it equal to 6: $f(7) = 2(7) + b = 14 +$ $b = 6$. Solve the equation $14 + b = 6$ by subtracting 14 from both sides to get $b = 6 - 14 = -8$.
**Faster approach:** Directly use the definition: since $f(7) = 6$, compute $b = 6 - 2(7) = 6 - 14 = -8$. For any similar linear function $f(x) = mx + b$ with a given $f(x_{0})$, compute $b = f(x_{0}) - mx_{0}$ immediately.'),
  ('80f9725d-741f-5028-b3a7-925d1726e3eb', 1, null, '**Choice B is correct.** If $f$ is 120% greater than $g$, then $f = g(1 + 1.20) = 2.20g$. If $h$ is 90% less than $f$, then $h = f(1 - 0.90) = 0.10f$. Substituting gives $h = 0.10(2.20g) = 0.22g$, so $h$ is $0.22$ times $g$.
**Choice A is incorrect.** $0.12$ would correspond to $h$ being $12%$ of $g$, but the correct computation yields $22%$ of $g$, not $12%$.
**Choice C is incorrect.** The entry "01.08" is not equal to $0.22$ and does not match the computed product $2.20 \times 0.10$.
**Choice D is incorrect.** $1.98$ would be close to $2 \times g$, but $h$ is much smaller than $g$ here (only $22%$ of $g$), so $1.98$ is not correct.
**Faster approach:** Convert each percent change to a multiplication factor ($+120% → 2.20$, $-90% → 0.10$) and multiply the factors: $2.20 \times 0.10 = 0.22$.'),
  ('74585b49-115d-5532-a2aa-bd7f11b2c628', 0, null, '**Choice A is correct.** The histogram for Team A shows scores clustered between about 25 and 40, so most values lie close to A’s mean; Team B’s histogram has values spread from about 15 to 50 (with peaks at the low and high ends), so B’s scores are much more spread out from its mean. Because standard deviation measures typical distance from the mean, Team A’s smaller spread implies a smaller standard deviation than Team B’s.
**Choice B is incorrect.** This claims Team A has the greater standard deviation, but the Team A scores are tightly clustered around the center while Team B’s scores are dispersed across a much wider range, so B actually has the larger standard deviation.
**Choice C is incorrect.** The two histograms have clearly different spreads: A’s scores are concentrated in a narrow interval (25–40) while B’s scores span roughly 15–50, so their standard deviations cannot be equal.
**Choice D is incorrect.** The histograms provide enough information about the relative spread of each distribution: Team B’s much wider range and bimodal spread indicate a larger standard deviation than Team A’s concentrated distribution.
**Faster approach:** Visually compare the horizontal spread (range and how far bars are from the center) of the two histograms — the distribution with the larger horizontal spread has the larger standard deviation. This works for any question comparing standard deviations from histograms.'),
  ('d9c7d587-2bbd-589e-bee5-d3c6e7baf21b', null, array['28']::text[], '**The correct answer is 28.** The given circle A has equation $x^{2} + (y - 5)^{2} = 7$, so its center is $(0,5)$ and its radius is $r =\sqrt{7}$. Translating the circle 91 units to the right moves the center to $(91,5)$ but does not change the radius, so circle B has equation $(x - 91)^{2} + (y - 5)^{2} = 7$. Thus $a = 7$ and $4a = 4 \cdot 7 = 28$.
**Faster approach:** Recognize that the constant on the right side of a circle’s equation is the squared radius and is unchanged by horizontal translation, so compute $4\times$ (right-hand constant) immediately: $4 \cdot 7 = 28$.'),
  ('c66ecaff-5a8e-50e5-80e7-eb85ca345251', null, array['8/5']::text[], '**The correct answer is 1.6.** At t = 0, h(0) = b = 40.96, so the height function is $h(t) = -16t^{2} + 40.96$. The object hits the ground when $h(t) = 0$, so solve $-16t^{2} + 40.96 = 0$. Rearranging gives $16t^{2} = 40.96$, so $t^{2} =$ $40.96/16 = 2.56$. Taking the positive square root (time is nonnegative) gives $t =\sqrt{2.56} = 1.6$ seconds.
**Faster approach:** Substitute $b$ immediately from $h(0) = b = 40.96$ and use the formula $t =\sqrt{b/16}$, then compute $\sqrt{40.96/16} =\sqrt{2.56} = 1.6$. This avoids extra algebraic steps.'),
  ('a18bed1e-32cc-5fd8-a1ee-afe6b0d28359', 3, null, '**Choice D is correct.** The graph shows the total rainfall is 2 centimeters at both $x = 2$ and $x = 4$, so the change in total rainfall over that interval is $0$ centimeters in $2$ hours. The rate (change in total per hour) is $0/2 = 0$ centimeters per hour.
**Choice A is incorrect.** Between $x = 2$ and $x = 4$ the total stays at 2 cm, so the rate is 0, not 2 cm/hr.
**Choice B is incorrect.** The steepest increase in the total occurs between $x = 0$ and $x = 2$ (from 0 to 2 cm in 2 hours), so the rate is larger there than between $x = 4$ and $x = 10$.
**Choice C is incorrect.** From $x = 0$ to $x = 2$ the total rainfall increases at a constant rate (slope = $1$ cm/hr), so the rate does not increase over that interval.
**Faster approach:** Note that the slope of the total-rainfall graph is the rainfall rate; identify flat segments (slope 0) and steepest sloped segment to determine where the rate is greatest.'),
  ('6a7f632b-96eb-59c0-8825-15588c5fd959', null, array['51']::text[], '**The correct answer is 51.** Let the three consecutive integers be $n$, $n + 1$, and $n + 2$, where $n + 2$ is the greatest. The sum of the other two is $n + (n + 1) = 2n + 1$. Subtracting the greatest gives $(2n + 1) - (n +$ $2) = n - 1$, and we are told this equals 48. So $n - 1 = 48$, which yields $n = 49$. Therefore the greatest integer is $n + 2 = 49 + 2 = 51$.
**Faster approach:** Represent the three consecutive integers as $n,n + 1,n + 2$, form the expression $(n) +$ $(n + 1) - (n + 2) = n - 1$, set it equal to 48, solve quickly for $n$, then add 2 to get the largest. This setup and single linear step works for every problem of this type.'),
  ('c8c098c4-bf23-5fa8-8e61-7c1e9545d881', 3, null, '**Choice D is correct.** When both dimensions are increased by 20%, each is multiplied by $1.20$, so the area is multiplied by $1.20^{2} = 1.44$. The new area is $2300 \times 1.44 = 2300 + 2300 \times 0.44 = 2300 + 1012 = 3312$ square inches.
**Choice A is incorrect.** The value shown ("2,32") is not equal to $3312$; it is far too small and does not reflect the $1.44$ area scale-up.
**Choice B is incorrect.** The value shown ("2,34") is also not $3312$ and similarly fails to account for both dimensions increasing by 20%.
**Choice C is incorrect.** The value shown ("2,76") is not the product $2300 \times 1.44$; it underestimates the correct scaled area.
**Faster approach:** Multiply the original area by $1.20^{2} = 1.44$. For any problem where both linear dimensions change by the same percent, square $1+$percent (in decimal) and multiply by the original area.'),
  ('eb9b5b4d-adf5-5427-940b-27267778a1dd', 2, null, '**Choice C is correct.** Solve $(x - 42)^{2} = 1$ by taking square roots: $x - 42 = \pm 1$, so $x = 42 \pm 1$, giving $x = 41$ and $x = 43$. The sum of the solutions is $41 + 43 = 84$, so choice C is correct.
**Choice A is incorrect.** 42 is the center value $42$, not the sum of the two symmetric solutions; the actual sum is double that center ($84$).
**Choice B is incorrect.** 43 is one of the individual solutions, not the sum of both solutions.
**Choice D is incorrect.** 85 is neither an individual solution nor the correct sum; it is 1 greater than the correct sum.
**Faster approach:** For $(x - h)^{2} = k$, the solutions are $h \pm\sqrt{k}$, so their sum is $2h$. Here $h = 42$, so the sum is $2(42) = 84$.'),
  ('550f6335-cb1a-5c0a-86f0-e45a224b4134', 0, null, '**Choice A is correct.** For the equation $5(kx - n) = -\frac{65}{14}x - \frac{85}{18}$ to have no solution, the $x$-coefficients must be equal while the constants differ. Expanding gives $5kx - 5n = -\frac{65}{14}x - \frac{85}{18}$. Equating $x$-coefficients: $5k = -\frac{65}{14}$, so $k = -\frac{65}{70} = -\frac{13}{14}$, which matches choice A. Because $n > 1$, the constants $-5n$ and $-\frac{85}{18}$ are indeed different, so the equation has no solution.
**Choice B is incorrect.** $-0.128 \approx -\frac{16}{125}$, which does not equal $-\frac{13}{14}$ obtained from $5k = -\frac{65}{14}$.
**Choice C is incorrect.** $\frac{3}{2}$ would give $5k = \frac{15}{2}$, not $-\frac{65}{14}$, so the $x$-coefficients would not match.
**Choice D is incorrect.** $0.52$ (or $\frac{13}{25}$) does not satisfy $5k = -\frac{65}{14}$, so it cannot produce the required identical $x$- coefficients.
**Faster approach:** For "no solution" in a linear equation, set the $x$-coefficients equal and solve for $k$; then check constants differ (here satisfied since $n > 1$).')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

