insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('4794268f-0ab7-5e80-86ac-65a59d58f4ce', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'If $9 + x = 6$, what is the value of $-18 - 2x$?', '["$-12$", "$-2$", "6", "24"]'::jsonb, 1, null),
  ('96e49acd-e58e-5d8b-9011-66bc0af4f95c', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'In the figure, line $l$ is parallel to line $m$. What is the value of $x$?', '["31", "69", "111", "131"]'::jsonb, 2, '![figure](/q/may25/005.webp)'),
  ('f7871343-d36c-5efe-a1d7-48deff0de548', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'The graph of the linear function $f$ is shown, where $y = f(x)$. Which equation defines $f$?', '["$f(x) = \\frac{3}{7}x - 5$", "$f(x) = \\frac{7}{3}x - 5$", "$f(x) = -\\frac{3}{7}x - 5$", "$f(x) = -\\frac{7}{3}x - 5$"]'::jsonb, 3, '![figure](/q/may25/006.webp)'),
  ('67e35ade-3365-5ae1-86c9-05f119207196', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'The function $t$ gives the estimated melting temperature, in degrees Celsius, of a DNA molecule as a function of the percent of guanine-cytosine (GC) content, $x$, in the DNA molecule. The graph of $y =$ $f(x)$ is shown. According to the graph, which of the following statements is NOT true?', '["For each increase of $x$ by 1, $f(x)$ increases by approximately $\\frac{2}{5}$.", "A DNA molecule with a GC content of 0% has an estimated melting temperature between $60°C$ and $65°C$.", "A DNA molecule with a GC content of 95% has an estimated melting temperature between $100°C$ and $105°C$.", "A DNA molecule with a GC content of 98% has an estimated melting temperature between $80°C$ and $90°C$."]'::jsonb, 4, '![figure](/q/may25/007.webp)'),
  ('a8e82a3e-3a09-5398-bd88-9b8a3b18d98c', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'In the xy-plane, line $s$ is parallel to line $t$. Line $s$ is defined by $y + 16 = 7x$. What is the slope of line $t$?', '["$-16$", "$-7$", "$7$", "$16$"]'::jsonb, 5, null),
  ('9dcb676e-f939-5efa-ad12-4cf5f3e4c6f3', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'Scientists collected fallen acorns that each housed a colony of the ant species _P. ohioensis_ and analyzed each colony’s structure. For any of these colonies, if the colony has $x$ worker ants, the equation $y = 0.67x + 2.6$, where $20 \le x \le 110$, gives the predicted number of larvae, $y$, in the colony. If one of these colonies has 39 worker ants, which of the following is closest to the predicted number of larvae in the colony?', '["29", "42", "54", "128"]'::jsonb, 6, null),
  ('d9dc57dd-49fa-5e8b-beb9-60a6ae034bb1', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', '$y > 5x - 4$ For which of the following tables are all the values of $x$ and their corresponding values of $y$ solutions to the given inequality?', '["![figure](/q/may25/008.webp)", "![figure](/q/may25/009.webp)", "![figure](/q/may25/010.webp)", "![figure](/q/may25/011.webp)"]'::jsonb, 7, null),
  ('7db50c81-cfc5-598c-b10b-91dc21214935', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'The given equation relates the variables $P,N,$ and $C$. Which expression represents the value of $C$ for distinct positive values of $P$ and $N$?
$P = N(34 - C)$', '["$C + \\frac{P}{N}$", "$34 + \\frac{P}{N}$", "$34 - \\frac{P}{C}$", "$34 - \\frac{P}{N}$"]'::jsonb, 8, null),
  ('b2693969-ffe0-5d90-8910-d588cea48e0f', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', '$x^{2} - 15x + 12 = 0$
What is the sum of the solutions to the given equation?', '["$15$", "$12$", "$3$", "$0$"]'::jsonb, 9, null),
  ('775c8c30-20ef-5ad4-be3e-931c96f637b0', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'The figure shown is a right rectangular pyramid, where $l = 18$ units, $w = 9$ units, and $h = 12$ units. What is the surface area, in square units, of the pyramid?', '[]'::jsonb, 10, '![figure](/q/may25/012.webp)'),
  ('111c1f73-857c-5f30-a86d-405ef055a0e9', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'The function $f(x) = \frac{1}{7}(x - 6)^{2} + 4$ gives a toy car’s height above the ground $f(x)$, in inches, $x$ seconds after it started moving on an elevated track, where $0 \le x \le 10$. Which of the following is the best interpretation of the vertex of the graph of $y = f(x)$ in the $xy$-plane?', '["The toy car’s minimum height was 4 inches above the ground.", "The toy car’s minimum height was 6 inches above the ground.", "The toy car’s height was 4 inches above the ground when it started moving.", "The toy car’s height was 6 inches above the ground when it started moving."]'::jsonb, 11, null),
  ('6c50a291-fb19-5b6f-8809-10c70e5f8559', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'In triangle $QRS$ shown, $QR < RS$. Which expression represents the length of $QS$?', '["$47\\cos Q$", "$47\\sin Q$", "$\\frac{47}{\\cos Q}$", "$\\frac{47}{\\sin Q}$"]'::jsonb, 12, '![figure](/q/may25/013.webp)'),
  ('86ab4502-5a38-5e83-bce3-eae6b97b6e2d', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'A researcher surveyed undergraduate students, graduate students, and postdoctoral students. The number of undergraduate students surveyed was 7,150% of the number of postdoctoral students surveyed and the number of graduate students surveyed was 45% of the number of undergraduate students surveyed. If there were 6,435 graduate students surveyed, what was the sum of the number of undergraduate students and postdoctoral students surveyed?', '[]'::jsonb, 13, null),
  ('9e1f69a8-d3ce-5570-99d5-2144c5a358e1', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'In the given system of equations, $t$ is a constant. If the system has no solution, what is the value of $t$?
$16x - 20y = 6y + 8$
$ty = 8x + \frac{1}{5}$', '[]'::jsonb, 14, null),
  ('fa5dec34-2e7b-5396-aba7-4f1c5a971741', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'The function $f$ is defined by the given equation. If $g(x) = f(x + 3)$, which of the following equations defines the function $g$?
$f(x) = 7(4)^{x}$', '["$g(x) = 21(4)^{x}$", "$g(x) = 448(4)^{x}$", "$g(x) = 21(12)^{x}$", "$g(x) = 343(64)^{x}$"]'::jsonb, 15, null),
  ('e8076572-847c-5e1b-b868-012360947377', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'The bone mineral density of a certain person’s thoracic spine was estimated to be $0.812$ grams per square centimeter. What is this estimated bone mineral density in grams per **square millimeter**? ($1$ centimeter = $10$ millimeters)', '["81.2", "8.12", "0.0812", "0.00812"]'::jsonb, 16, null),
  ('d2cd26f8-75c8-5d7b-ae2c-61db2f59f839', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'Which expression is a factor of $49p^{19} - 121p^{17}$?', '["$7p + 11$", "$49p^{2} + 121$", "$11p - 7$", "$-72p^{40}$"]'::jsonb, 17, null),
  ('85eeb84b-c425-5192-ba41-6642ffa1c2ee', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', '$\frac{5}{9} (5x + 9)(x +\sqrt{5k + 9})(x -\sqrt{5k + 9}) = 0$
In the given equation, $k$ is a positive constant. The product of the solutions to the equation is 72. What is the value of $k$?', '[]'::jsonb, 18, null),
  ('30093d4e-f43e-57b9-b61e-20fa4354c99d', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'A right rectangular prism has a base area of $56t$ square centimeters ($cm^{2}$). The length of the base of the rectangular prism is $\frac{14}{3}$ cm, and the height of the rectangular prism is 3 cm. Which expression represents the surface area, in $cm^{2}$, of the right rectangular prism?', '["$112t + 56$", "$184t + 28$", "$1,680t + 28$", "$168t$"]'::jsonb, 19, null),
  ('5fe09507-af14-5cd6-bad6-944accbb8258', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'In the $xy$-plane, a unit circle with center at the origin $O$ contains point $A$ with coordinates $(1,0)$ and point $B$ with coordinates $(\frac{5}{\sqrt{34}},-\frac{3}{\sqrt{34}})$. If the measure of angle $AOB$ is $p$ radians, what is the value of $\frac{\cos p}{\sin p}$?', '[]'::jsonb, 20, null),
  ('cd6f8cfb-d01b-5370-a3a2-c212890c753d', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'The function $h$ is defined by
$h(x) = -\sqrt{x^{2} + bx + c}$
, where $b$ and $c$ are constants. In the $xy$-plane, the graph of $y = h(x)$ contains the points $(2,0)$ and $(0,-\sqrt{334})$. If $h(m) = 0$, what is the greatest possible value of $m$?', '[]'::jsonb, 21, null),
  ('5cb758f5-7ee8-503e-933f-3d98a4daaf90', 'e61ad86b-5b40-5b62-9798-dc2aa0cd99f1', 'A computer repair specialist charges $160$ for the first two hours of repair plus an hourly fee for each additional hour. The total cost for $6$ hours of repair is $360$. Which function $f$ gives the total cost, in dollars, for $x$ hours of repair, where $x \ge 2$?', '["$f(x) = 50x + 60$", "$f(x) = 50x + 160$", "$f(x) = 60x$", "$f(x) = 60x + 160$"]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
